//! Conducting sheets on cylindrical grids against the black-box openEMS
//! (design §5.16.2; fixtures `tests/fixtures/openems/cyl_sheet_*`,
//! regenerated by `scripts/openems-oracle/gen-cyl.sh`): a closed half-wave
//! coaxial cavity (`a = 2 mm`, `b = 6 mm`, `L = 30 mm`) whose TEM mode
//! (≈ 5 GHz) rings down with a lossy inner tube (`ρ = const` sheet) or a
//! resistive fin (`α = const` sheet, at `α = π/2` and on the `α = 0` seam).
//!
//! openEMS's sheet model is not ems's slab model (§5.9), on cylindrical
//! grids as on Cartesian ones: openEMS's tube has half the loss (twice the
//! `Q`), its thin resistive fin is nearly reactive (the mode detunes by
//! −13 %), and its fin on the seam has no effect. ems's native values are
//! the analytic ones (`tests/cylindrical_sheet.rs`); for files ems runs
//! openEMS's model (`compile/openems_sheet.rs`) and the signals agree.
//! Also: openEMS ignores plane waves on cylindrical grids (`cyl_planewave`).
#![cfg(feature = "xml")]

use std::f64::consts::TAU;
use std::path::{Path, PathBuf};

use ems::Simulation;

fn fixture(case: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/openems")
        .join(case)
}

/// `(t, v)` of an openEMS probe file.
fn read_probe(path: &Path) -> (Vec<f64>, Vec<f64>) {
    let text = std::fs::read_to_string(path).unwrap();
    text.lines()
        .filter(|l| !l.starts_with('%') && !l.trim().is_empty())
        .map(|l| {
            let mut it = l.split_whitespace().map(|x| x.parse::<f64>().unwrap());
            (it.next().unwrap(), it.next().unwrap())
        })
        .unzip()
}

/// `(f, Q)` of the ring-down after 2 ns: spectral peak in 4–6 GHz, then a
/// least-squares fit of the log of the energy per period.
fn q_of(t: &[f64], v: &[f64]) -> (f64, f64) {
    let dt = t[1] - t[0];
    let t0 = t.iter().position(|&x| x >= 2e-9).unwrap();
    let tail = &v[t0..];
    let spec = |f: f64| {
        let (mut re, mut im) = (0.0, 0.0);
        for (n, &x) in tail.iter().enumerate() {
            let (s, c) = (TAU * f * n as f64 * dt).sin_cos();
            re += x * c;
            im -= x * s;
        }
        re.hypot(im)
    };
    let (mut lo, mut hi) = (4e9, 6e9);
    for _ in 0..60 {
        let (a, b) = (lo + (hi - lo) / 3.0, hi - (hi - lo) / 3.0);
        if spec(a) < spec(b) {
            lo = a;
        } else {
            hi = b;
        }
    }
    let f = 0.5 * (lo + hi);
    let per = 1.0 / (f * dt);
    let n = (tail.len() as f64 / per).floor() as usize;
    let pts: Vec<(f64, f64)> = (0..n)
        .map(|p| {
            let (a, b) = ((p as f64 * per) as usize, ((p + 1) as f64 * per) as usize);
            let e: f64 = tail[a..b].iter().map(|x| x * x).sum::<f64>() / (b - a) as f64;
            ((p as f64 + 0.5) * per * dt, e.ln())
        })
        .collect();
    let m = pts.len() as f64;
    let (mx, my) = pts
        .iter()
        .fold((0.0, 0.0), |a, p| (a.0 + p.0 / m, a.1 + p.1 / m));
    let slope = pts.iter().map(|p| (p.0 - mx) * (p.1 - my)).sum::<f64>()
        / pts.iter().map(|p| (p.0 - mx).powi(2)).sum::<f64>();
    (f, -TAU * f / slope)
}

/// `(f, Q)` of openEMS's ring-down for `case`.
fn q_of_file(case: &str) -> (f64, f64) {
    let (t, v) = read_probe(&fixture(case).join("v0"));
    let q = q_of(&t, &v);
    eprintln!("{case}: openEMS f {:.4} GHz Q {:.2}", q.0 / 1e9, q.1);
    q
}

#[test]
fn cylindrical_conducting_sheets_match_openems() {
    let none = q_of_file("cyl_sheet_none");
    // Lossy tube: openEMS's model has about half the loss of the exact
    // slab (Q 403 against 195.9, ems's native value in
    // tests/cylindrical_sheet.rs).
    let tube = q_of_file("cyl_sheet_tube");
    assert!((tube.1 / 195.9 - 2.06).abs() < 0.05, "{tube:?}");
    // Resistive fin: openEMS's model detunes the mode by about −13 %.
    let fin = q_of_file("cyl_sheet_fin");
    let shift = fin.0 / none.0 - 1.0;
    assert!(
        (-0.16..-0.10).contains(&shift),
        "openEMS fin detuning {shift}"
    );
    // The same fin drawn on the α = 0 seam: no effect in openEMS (it
    // updates the seam's α = 2π copy, where the fin is not).
    let seam = q_of_file("cyl_sheet_seam");
    assert!((seam.0 / none.0 - 1.0).abs() < 1e-6 && seam.1.abs() > 1e4);
    // ems reproduces the model for files: the ring-down signals.
    for case in [
        "cyl_sheet_none",
        "cyl_sheet_tube",
        "cyl_sheet_fin",
        "cyl_sheet_seam",
    ] {
        for (n, e) in probe_l2(case, "model.xml") {
            assert!(e < 1e-4, "{case}/{n}: {e:e}");
        }
    }
}

/// openEMS ignores a plane wave on a cylindrical grid (no field at all,
/// no message; `cyl_planewave`); ems drops it with a warning.
#[test]
fn cylindrical_plane_wave_is_ignored_like_openems() {
    let text = std::fs::read_to_string(fixture("cyl_planewave").join("e_in")).unwrap();
    let rows: Vec<Vec<f64>> = text
        .lines()
        .filter(|l| !l.starts_with('%') && !l.trim().is_empty())
        .map(|l| l.split_whitespace().map(|x| x.parse().unwrap()).collect())
        .collect();
    assert!(rows.len() > 10);
    assert!(rows.iter().all(|r| r[1..].iter().all(|&x| x == 0.0)));
    let mut sim = Simulation::from_xml(fixture("cyl_planewave").join("model.xml")).unwrap();
    assert!(sim.plane_wave("pw").is_none());
    assert!(
        sim.warnings()
            .iter()
            .any(|w| w.contains("plane-wave excitation(s) ignored")),
        "{:?}",
        sim.warnings()
    );
    sim.step(50);
    assert_eq!(sim.engine().energy(), 0.0);
}

/// The `keep:` probes of `case` (`meta.txt`).
fn kept(case: &str) -> Vec<String> {
    let text = std::fs::read_to_string(fixture(case).join("meta.txt")).unwrap();
    text.lines()
        .find_map(|l| l.strip_prefix("keep:"))
        .unwrap()
        .split_whitespace()
        .map(String::from)
        .collect()
}

/// Relative L2 difference of each kept scalar probe of `case` (openEMS's
/// files) against ems run on `model` (both codes step with the model's
/// `TimeStep`, or with openEMS's own step, which ems reproduces to ~1e-8).
fn probe_l2(case: &str, model: &str) -> Vec<(String, f64)> {
    let xml = std::fs::read_to_string(fixture(case).join(model)).unwrap();
    probe_l2_xml(case, model, &xml)
}

/// [`probe_l2`] for ems run on the model text `xml` (labelled `model`).
fn probe_l2_xml(case: &str, model: &str, xml: &str) -> Vec<(String, f64)> {
    probe_l2_sim(case, model, Simulation::from_xml_str(xml).unwrap())
}

/// [`probe_l2`] for the simulation `sim` (labelled `model`).
fn probe_l2_sim(case: &str, model: &str, mut sim: Simulation) -> Vec<(String, f64)> {
    let res = sim.run().unwrap();
    kept(case)
        .into_iter()
        .map(|n| {
            let (t, v) = read_probe(&fixture(case).join(&n));
            let p = res.probe(&n).unwrap();
            let (et, ev) = (p.times(), p.scalar().unwrap());
            let (mut num, mut den) = (0.0, 0.0);
            // Both codes step with openEMS's time step (bit for bit since
            // §5.16.8); ems's samples are interpolated to openEMS's times
            // (printed with 12 digits: the last may lie just above ems's).
            let dt = et[1] - et[0];
            for (&ti, &vi) in t.iter().zip(&v) {
                let k = et.partition_point(|&x| x < ti - 1e-6 * dt);
                let e = if k < et.len() && (et[k] - ti).abs() < 1e-6 * dt {
                    ev[k]
                } else if k > 0 && k < et.len() && et[k] - et[k - 1] < 1.5 * dt {
                    let s = (ti - et[k - 1]) / (et[k] - et[k - 1]);
                    ev[k - 1] + s * (ev[k] - ev[k - 1])
                } else {
                    0.0
                };
                num += (e - vi) * (e - vi);
                den += vi * vi;
            }
            let e = (num / den).sqrt();
            eprintln!("{case}/{model}/{n}: relative L2 {e:.2e}");
            (n, e)
        })
        .collect()
}

/// `CellConstantMaterial` on a cylindrical grid (`cyl_cellconst`): openEMS
/// samples each cell at its `(ρ, α, z)` midpoint (its probes are
/// bit-identical to the box snapped to the cells whose midpoints it holds;
/// the box's ρ_max face lies between the midpoint and the centroid of a
/// cell), and so does ems. On z edges at a radial interface openEMS
/// weighs the two radial halves of the dual face by `Δρ_h·ρ` of the dual
/// line bounding each half, ems natively by their exact annular areas
/// (first order in `Δρ/ρ`, design §5.15); models read from openEMS files
/// use openEMS's weight: 5e-7…8e-6 (1.2e-4…1.7e-3 with the exact areas).
#[test]
fn cylindrical_cell_constant_material_matches_openems() {
    for (n, e) in probe_l2("cyl_cellconst", "model.xml") {
        assert!(e < 3e-5, "{n}: {e:e}");
    }
    // The cell 6.5..7 mm (midpoint 6.75 inside the box face 6.752, its
    // centroid 6.7531 outside) is dielectric: a ρ edge in it reads ε = 4.
    let doc = csx::OpenEmsDocument::read_file(fixture("cyl_cellconst").join("model.xml")).unwrap();
    let (fdtd, _) = ems::Fdtd::from_document(&doc).unwrap();
    let c = ems::compile::compile(&doc.structure, &fdtd, &ems::CompileOptions::default()).unwrap();
    // ρ lines 1, 1.5, …: line 11 is 6.5 mm; α line 4, z line 5 (inside).
    let idx = c.grid.index([11, 4, 5]);
    assert_eq!(c.materials.eps_r(ems::Axis::X)[idx], 4.0);
    let idx = c.grid.index([12, 4, 5]);
    assert_eq!(c.materials.eps_r(ems::Axis::X)[idx], 1.0);
}

/// Radial material interfaces without `CellConstantMaterial`
/// (`cyl_radial`: a dielectric, magnetic, lossy box with its ρ faces on
/// mesh lines, its α and z faces inside cells): openEMS samples the same
/// quarter-cell centres as csx but weighs the radial halves differently
/// (z edges `Δρ_h·ρ_b`, α edges and H_ρ faces `Δρ_h`; `compile::cylavg`,
/// design §5.15). Models read from files use openEMS's weights and agree
/// closely; with csx's weights (ems's own averages, `openems_run` off)
/// the probes differ by about 1e-3.
#[test]
fn cylindrical_radial_interfaces_match_openems() {
    let case = "cyl_radial";
    for (n, e) in probe_l2(case, "model.xml") {
        assert!(e < 3e-5, "{n}: {e:e}");
    }
    let xml = std::fs::read_to_string(fixture(case).join("model.xml")).unwrap();
    let doc = csx::OpenEmsDocument::from_xml_str(&xml).unwrap();
    let copts = ems::CompileOptions::default();
    let sim = Simulation::from_document_with(&doc, &copts, |f| f.openems_run(false)).unwrap();
    let worst = probe_l2_sim(case, "native averages", sim)
        .into_iter()
        .fold(0.0f64, |m, (_, e)| m.max(e));
    assert!(worst > 3e-4, "{worst:e}");
}

/// A radial-line port's properties (`cyl_radial_port`: the feed ring,
/// the split feed resistor, the voltage lines and the flat current rings
/// that `RadialLinePort` writes, on a quarter sector with a short at
/// 20 mm): openEMS runs them like any boxes in `(ρ, α, z)`, and ems reads
/// the file the same way (openEMS's PMC walls half a cell inside, its
/// lumped-element update).
#[test]
fn cylindrical_radial_line_port_runs_like_openems() {
    for (n, e) in probe_l2("cyl_radial_port", "model.xml") {
        assert!(e < 1e-4, "{n}: {e:e}");
    }
}

/// The `ρ_min` boundary of a grid with the axis is no boundary: openEMS's
/// probes are bit-identical with `xmin="PEC"` and `"PMC"` (black box, the
/// `adv_cyl_axis` model), and so are ems's (openEMS's PMC emulation for
/// files skips the axis; it had zeroed the `H_α` ring around it).
#[test]
fn axis_ignores_the_rho_min_boundary() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/openems/adv_cyl_axis");
    let pec = std::fs::read_to_string(dir.join("model.xml")).unwrap();
    assert!(pec.contains("xmin=\"PEC\""));
    let pmc = pec.replace("xmin=\"PEC\"", "xmin=\"PMC\"");
    let run = |xml: &str| {
        let mut sim = Simulation::from_xml_str(xml).unwrap();
        sim.run().unwrap()
    };
    let (a, b) = (run(&pec), run(&pmc));
    for n in ["uz_a", "uz_axis", "ur_a"] {
        assert_eq!(
            a.probe(n).unwrap().values(),
            b.probe(n).unwrap().values(),
            "{n}"
        );
    }
}

/// Boxes at `α > π` on a closed `[0, 2π]` grid (`cyl_wrap_*`): csx selects
/// the edges of sources and lumped elements within a bounding box whose
/// α range is normalised to `[−π, π)` and missed them; ems re-selects them
/// periodically (`compile::cylindrical`). A half-ring resistor over
/// `[π, 2π)` then agrees with openEMS to 1e-7, a source over `[π, 3π/2]`
/// to 1e-6.
#[test]
fn cylindrical_boxes_past_pi_match_openems() {
    for case in ["cyl_wrap_lumped", "cyl_wrap_exc"] {
        for (n, e) in probe_l2(case, "model.xml") {
            let tol = if n == "uz_c" { 3e-4 } else { 2e-5 };
            assert!(e < tol, "{case}/{n}: {e:e}");
        }
    }
}

/// A lumped ring over exactly `[0, 2π]` (`cyl_wrap_ring`): openEMS reduces
/// the bound 2π to 0, the element lands on the α = 0 line, where openEMS
/// applies nothing, and has no effect at all (its probes equal ems's
/// without the element, 1e-7). ems keeps the ring as drawn (openEMS is
/// wrong here, design §5.15) and warns.
#[test]
fn cylindrical_lumped_ring_ending_at_tau_vanishes_in_openems() {
    let case = "cyl_wrap_ring";
    let xml = std::fs::read_to_string(fixture(case).join("model.xml")).unwrap();
    let start = xml.find("<LumpedElement").unwrap();
    let end = xml.find("</LumpedElement>").unwrap() + "</LumpedElement>".len();
    let without = format!("{}{}", &xml[..start], &xml[end..]);
    for (n, e) in probe_l2_xml(case, "without the element", &without) {
        assert!(e < 3e-4, "{n}: {e:e}");
    }
    for (n, e) in probe_l2(case, "model.xml") {
        if n != "uz_c" {
            assert!(e > 0.1, "{n}: {e:e}");
        }
    }
    let sim = Simulation::from_xml_str(&xml).unwrap();
    assert!(
        sim.warnings()
            .iter()
            .any(|w| w.contains("openEMS reduces each alpha bound modulo 2*pi")),
        "{:?}",
        sim.warnings()
    );
}

/// Current boxes over α sectors of a closed grid (`cyl_current_seam`,
/// z-normal boxes on a coax excited over a quarter of the ring): openEMS
/// integrates on the dual α lines around the box, clamped to its lines
/// `α_{1/2} … α_{N−1/2}`, so a box from α = 0 or to 2π leaves out the
/// column on the seam (`[0, π]` reads columns 1…4, as `[π/4, π]`;
/// `[0, π/4]` collapses to a line and is dropped). ems does the same for
/// files (it read half the seam column more, 1.7 relative L2 here); a box
/// over the whole ring keeps ems's closed loop (openEMS: columns 1…7).
#[test]
fn cylindrical_current_boxes_at_the_seam_match_openems() {
    let case = "cyl_current_seam";
    for (n, e) in probe_l2(case, "model.xml") {
        if n == "i_full" {
            assert!(e > 0.05, "{n}: {e:e}");
        } else {
            assert!(e < 3e-3, "{n}: {e:e}");
        }
    }
    let xml = std::fs::read_to_string(fixture(case).join("model.xml")).unwrap();
    let mut sim = Simulation::from_xml_str(&xml).unwrap();
    assert!(sim.run().unwrap().probe("i_first").is_none());
}
